import logging
from taf.internal.managedobject import ManagedObject
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection
from taf.internal.rpc.pyro.exception import (RequiredSoftwareMissing,
                                             RequiredPackageMissing)
from .sys_command import (SysCommand, CygwinCommand, LinuxCommand)


class RemoteEnvironment(ManagedObject):
    def __init__(self, python_path, hostname, username=None, password=None):
        super(RemoteEnvironment, self).__init__()
        self._hostname = hostname
        self._username = username
        self._password = password
        self._python_path = python_path
        self._managed_connection = ManagedSshConnection(hostname, username, password)
        self.add_prerequisite(self._managed_connection)
        self._syscommand = None

    @property
    def hostname(self):
        return self._hostname

    @property
    def username(self):
        return self._username

    @property
    def password(self):
        return self._password

    @property
    def connection(self):
        return self._managed_connection.ssh_connection

    @property
    def is_connected(self):
        return self._managed_connection.ssh_connection.is_connected

    @property
    def syscommand(self):
        return self._syscommand

    def check_required_software(self, required_softwares):

        for software in required_softwares:
            output = self._syscommand.get_app_path(software)
            logging.debug('check_required_software get output -->{}'.format(output))
            no_software_str = self._generate_no_software_target_string(software)
            logging.debug('no_software_str is  -->{}'.format(no_software_str))
            if not output or no_software_str in output:
                raise RequiredSoftwareMissing('required software {} is missing'.format(software))

    def check_required_packages(self, required_packages):
        if not required_packages:
            return

        packages = self._syscommand.pip_list(self._python_path)
        if not packages:
            raise RequiredPackageMissing('no package already installed')
        logging.info("already installed packages :{}".format(packages))

        required_packages = [(package_name.lower(), version) for package_name, version in required_packages]
        packages = {key.lower(): value for key, value in packages.items()}

        for package_name, version in required_packages:
            if package_name not in packages:
                raise RequiredPackageMissing('required package {},{} is missing'.format(package_name, version))
            elif version and version != packages[package_name]:
                raise RequiredPackageMissing('required package {},{} is missing'.format(package_name, version))
            else:
                pass

    @staticmethod
    def _generate_no_software_target_string(path):
        # work for cygwin
        normalized_path = path.replace('\\', '/')
        if "/" not in normalized_path:
            no_software_str = 'no ' + normalized_path
        else:
            software_name = normalized_path.split("/")[-1]
            no_software_str = 'no ' + software_name

        return no_software_str

    def _setup(self):
        self._syscommand = self._create_cygwin_command(self._managed_connection.ssh_connection)\
            if self._is_remote_server_on_cygwin() \
            else self._create_linux_command(self._managed_connection.ssh_connection)

    def _create_cygwin_command(self, ssh_connection):
        return CygwinCommand(ssh_connection)

    def _create_linux_command(self, ssh_connection):
        return LinuxCommand(ssh_connection)

    def _is_remote_server_on_cygwin(self):
        output = SysCommand.get_system_information(self._managed_connection.ssh_connection)
        if 'cygwin' in output.lower():
            return True
        return False
